import {
  createBrowserRouter,
  RouterProvider,
  type RouteObject,
} from 'react-router';

export const routes: RouteObject[] = [
  { path: '/', element: <p>home</p> },
  { path: '/about', element: <p>about</p> },
];

export const router = createBrowserRouter(routes);

export function App() {
  return <RouterProvider router={router} />;
}
